// The cem-0.3 portable packet (protocol/cem-0.3) is generated by the
// independent interop consumer. This native consumer rebuilds every packet
// repository from the raw manifest alone and reads every case through the
// native single-profile status verifier (CEM-SM-016, CEM-SM-018). Every
// case must agree exactly with the portable declared result: no per-case
// divergence is admitted.

const portable03ManifestSHA256 = "cbb9b85e8d9085e1343a4b6e32e1047c62265154266da48f8d8889db3a58818e"

type portable03File struct {
	Path, Mode, ContentFile, Object string
	Content                         *string
}

type portable03Manifest struct {
	Spec, QualifiedRuntime string
	Repositories           []struct{ Name, ObjectFormat, Envelope string }
	Commits                []struct {
		Name, Repository, Message, Tree, Revision string
		Files                                     []portable03File
	}
	Cases []struct {
		Name, Repository, Map, ExpectedBase, TargetArgument string
		StructuralRuntimeGated                              bool
		Declared                                            struct {
			Outcome, Stage string
			Code           *string
			IssueCodes     []string
		}
		Native struct{ Kind, Code, Note string }
	}
	ArtifactSHA256 map[string]string
}

func portable03Git(t *testing.T, dir string, stdin []byte, env []string, args ...string) string {
	t.Helper()
	command := exec.CommandContext(t.Context(), "git", append([]string{"-c", "maintenance.auto=false", "-c", "gc.auto=0", "-c", "core.autocrlf=false"}, args...)...)
	command.Dir = dir
	command.Env = append([]string{"PATH=" + os.Getenv("PATH"), "GIT_CONFIG_NOSYSTEM=1", "GIT_CONFIG_GLOBAL=" + os.DevNull,
		"GIT_AUTHOR_NAME=Portable Proof", "GIT_AUTHOR_EMAIL=proof@example.invalid",
		"GIT_COMMITTER_NAME=Portable Proof", "GIT_COMMITTER_EMAIL=proof@example.invalid",
		"GIT_AUTHOR_DATE=2026-01-01T00:00:00Z", "GIT_COMMITTER_DATE=2026-01-01T00:00:00Z"}, env...)
	if stdin != nil {
		command.Stdin = bytes.NewReader(stdin)
	}
	var stderr bytes.Buffer
	command.Stderr = &stderr
	out, err := command.Output()
	if err != nil {
		t.Fatalf("git %v: %v: %s", args, err, stderr.Bytes())
	}
	return strings.TrimSpace(string(out))
}

func TestCEMSM016NativePortable03Vectors(t *testing.T) {
	kit, err := filepath.Abs("../../../protocol/cem-0.3")
	if err != nil {
		t.Fatal(err)
	}
	raw := portableRead(t, filepath.Join(kit, "vectors", "manifest.json"))
	if got := fmt.Sprintf("%x", sha256.Sum256(raw)); got != portable03ManifestSHA256 {
		t.Fatalf("cem-0.3 manifest digest changed: %s", got)
	}
	var manifest portable03Manifest
	if err := json.Unmarshal(raw, &manifest); err != nil {
		t.Fatal(err)
	}
	if manifest.Spec != "cem/0.3" || len(manifest.Cases) != 211 || len(manifest.ArtifactSHA256) != 211 {
		t.Fatal("cem-0.3 vector matrix changed")
	}
	artifacts := map[string][]byte{}
	for path, want := range manifest.ArtifactSHA256 {
		data := portableRead(t, filepath.Join(kit, path))
		if got := fmt.Sprintf("%x", sha256.Sum256(data)); got != want {
			t.Fatalf("artifact %s digest = %s, want %s", path, got, want)
		}
		artifacts[path] = data
	}
	root, err := filepath.EvalSymlinks(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	repos := map[string]string{}
	for _, r := range manifest.Repositories {
		dir := filepath.Join(root, r.Name)
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatal(err)
		}
		portable03Git(t, dir, nil, nil, "init", "-q", "--object-format="+r.ObjectFormat, "-b", "main")
		repos[r.Name] = dir
	}
	for _, c := range manifest.Commits {
		dir := repos[c.Repository]
		env := []string{"GIT_INDEX_FILE=" + filepath.Join(t.TempDir(), "index")}
		for _, f := range c.Files {
			oid := f.Object
			if f.Mode != "160000" {
				var data []byte
				if f.Content != nil {
					data = []byte(*f.Content)
				} else if data = artifacts["vectors/"+f.ContentFile]; data == nil {
					t.Fatalf("commit %s names unpinned %s", c.Name, f.ContentFile)
				}
				oid = portable03Git(t, dir, data, nil, "hash-object", "-w", "--no-filters", "--stdin")
			}
			portable03Git(t, dir, nil, env, "update-index", "--add", "--cacheinfo", f.Mode+","+oid+","+f.Path)
		}
		tree := portable03Git(t, dir, nil, env, "write-tree")
		revision := portable03Git(t, dir, nil, env, "commit-tree", tree, "-m", c.Message)
		if tree != c.Tree || revision != c.Revision {
			t.Fatalf("commit %s rebuilt as %s/%s, want %s/%s", c.Name, tree, revision, c.Tree, c.Revision)
		}
	}
	for _, r := range manifest.Repositories {
		dir := repos[r.Name]
		switch r.Envelope {
		case "default":
		case "object-alternates":
			writeFile(t, dir, ".git/objects/info/alternates", filepath.Join(dir, "absent-alternate")+"\n")
		default:
			t.Fatalf("unknown envelope %s", r.Envelope)
		}
	}
	for i, c := range manifest.Cases {
		t.Run("CEM-SM-016 native "+c.Name, func(t *testing.T) {
			dir := repos[c.Repository]
			mapPath := fmt.Sprintf("vector-%03d.cem.json", i)
			writeFile(t, dir, mapPath, string(artifacts[c.Map]))
			defer os.Remove(filepath.Join(dir, mapPath))
			options := ReadOptions{MapPath: mapPath, ExpectedBase: c.ExpectedBase, Target: c.TargetArgument, SingleSpec: "cem/0.3"}
			result, err := openSession(t, dir).Read(context.Background(), "status", options)
			kind, code := portable03NativeOutcome(t, result, err)
			wantKind, wantCode := portable03Projection(t, c.Declared.Outcome, c.Declared.Stage, c.Declared.Code, c.Declared.IssueCodes)
			if c.Native.Kind != wantKind || c.Native.Code != wantCode {
				t.Fatalf("packet native %+v is not the projection %s:%s of the portable result", c.Native, wantKind, wantCode)
			}
			if kind != wantKind || code != wantCode {
				t.Fatalf("native %s:%s, portable %s/%s projects %s:%s", kind, code, c.Declared.Outcome, c.Declared.Stage, wantKind, wantCode)
			}
		})
	}
}

// portable03Projection maps a portable verify-03 result onto the native status
// shape: ACCEPT is valid; a binding, verification or drift REJECT is the first
// verifier issue; a wire REJECT or any UNSUPPORTED is the top-level error code.
func portable03Projection(t *testing.T, outcome, stage string, code *string, issues []string) (string, string) {
	t.Helper()
	switch {
	case outcome == "ACCEPT":
		return "valid", ""
	case outcome == "REJECT" && (stage == "binding" || stage == "verification" || stage == "drift") && len(issues) == 1:
		return "issue", issues[0]
	case (outcome == "REJECT" || outcome == "UNSUPPORTED") && code != nil:
		return "error", *code
	}
	t.Fatalf("unprojectable portable result %s/%s", outcome, stage)
	return "", ""
}

func portable03NativeOutcome(t *testing.T, result map[string]any, err error) (string, string) {
	t.Helper()
	if err != nil {
		return "error", cemcode.CodeOf(err)
	}
	verification, _ := result["verification"].(map[string]any)
	if verification == nil {
		t.Fatalf("status without verification: %#v", result)
	}
	if verification["valid"] == true {
		return "valid", ""
	}
	issues, _ := verification["issues"].([]any)
	if len(issues) == 0 {
		t.Fatalf("invalid verification without issues: %#v", verification)
	}
	return "issue", issues[0].(map[string]any)["code"].(string)
}
